import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '20px 40px',
      background: '#120731',
      borderBottom: '1px solid rgba(255,255,255,0.1)'
    }}>
      <div style={{ fontSize: '20px', fontWeight: 'bold' }}>
        <Link to="/" style={{ color: '#FFC85C', textDecoration: 'none' }}>
          🎓 UniEquipment Rental
        </Link>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
        <Link to="/" style={{ color: '#FFF', textDecoration: 'none' }}>หน้าแรก</Link>

        {/* เมนูเฉพาะ Member */}
        {user.role === 'member' && (
          <Link to="/my-borrowings" style={{ color: '#FFF', textDecoration: 'none' }}>ประวัติการยืมของฉัน</Link>
        )}

        {/* เมนูเฉพาะ Admin */}
        {user.role === 'admin' && (
          <Link to="/admin" style={{ color: '#FF653F', textDecoration: 'none', fontWeight: 'bold' }}>
            🛡️ จัดการหลังบ้าน (Admin)
          </Link>
        )}

        {/* ส่วนแสดงสถานะผู้ใช้ / ปุ่ม Login - Logout */}
        {user.role === 'guest' ? (
          <Link to="/login" style={{
            background: '#FFC85C',
            color: '#1E104E',
            padding: '8px 16px',
            borderRadius: '6px',
            textDecoration: 'none',
            fontWeight: 'bold'
          }}>
            เข้าสู่ระบบ
          </Link>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <span style={{ fontSize: '14px', color: '#DDD' }}>
              👤 {user.name} <strong style={{ color: '#FFC85C' }}>({user.role})</strong>
            </span>
            <button 
              onClick={() => { logout(); navigate('/'); }}
              style={{
                background: '#FF653F',
                color: '#FFF',
                border: 'none',
                padding: '6px 12px',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: 'bold'
              }}
            >
              ออกจากระบบ
            </button>
          </div>
        )}
      </div>
    </nav>
  );
}
